package dev.hackuniversity.playground;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * The entry point. Spring Boot scans this package and every package below it,
 * so new classes go under dev.hackuniversity.playground.
 */
@SpringBootApplication
public class PlaygroundApplication {

    public static void main(String[] args) {
        SpringApplication.run(PlaygroundApplication.class, args);
    }
}

@AnalyzeClasses(packages = "dev.hackuniversity.shopfront", importOptions = ImportOption.DoNotIncludeTests.class)
class ArchitectureTest {

    @ArchTest
    static final ArchRule controllersNeverUseRepositories = noClasses()
            .that().areAnnotatedWith(RestController.class)
            .should().dependOnClassesThat().areAssignableTo(Repository.class)
            .because("controllers call services, and only services reach the database");

    @ArchTest
    static final ArchRule controllersNeverReturnEntities = methods()
            .that().areDeclaredInClassesThat().areAnnotatedWith(RestController.class)
            .and().arePublic()
            .should(returnNoEntity())
            .because("an entity in a response leaks columns like password_hash and loads lazy data while JSON is written");

    @ArchTest
    static final ArchRule noFieldInjection = GeneralCodingRules.NO_CLASSES_SHOULD_USE_FIELD_INJECTION
            .because("constructor injection makes dependencies visible and lets plain unit tests build the class");

@Service
@Transactional(readOnly = true)
public class OrderService {

    private static final Sort NEWEST_FIRST = Sort.by(Sort.Direction.DESC, "placedAt", "id");

    private final OrderRepository orders;
    private final ProductRepository products;
    private final CustomerRepository customers;
    private final ShopProperties shop;
    private final Clock clock;

    public OrderService(OrderRepository orders, ProductRepository products, CustomerRepository customers,
            ShopProperties shop, Clock clock) {
        this.orders = orders;
        this.products = products;
        this.customers = customers;
        this.shop = shop;
        this.clock = clock;
    }

@Configuration(proxyBeanMethods = false)
public class ClockConfig {

    @Bean
    Clock clock(@Value("${app.clock.fixed:}") String fixedInstant) {
        if (fixedInstant.isBlank()) {
            return Clock.systemUTC();
        }
        return Clock.fixed(Instant.parse(fixedInstant), ZoneOffset.UTC);
    }
}

@Validated
@ConfigurationProperties("shop")
public record ShopProperties(
        @NotBlank @Pattern(regexp = "[A-Z]{3}") String currency,
        @NotNull @DecimalMin("0.0") @DecimalMax("0.5") @Digits(integer = 1, fraction = 4) BigDecimal taxRate,
        @PositiveOrZero long freeShippingOverCents,
        @Valid @NotNull Jwt jwt) {

    public record Jwt(@NotBlank @Size(min = 32) String secret, @NotNull Duration ttl) {}

    /** The tax rate in basis points (hundredths of a percent): 0.0825 is 825. */
    public int taxRateBasisPoints() {
        return taxRate.movePointRight(4).intValueExact();
    }
}
